Definition sh_bytes : gmap Z (bv 8) :=
  list_to_map (List.concat [
    sh_bytes_chunk0; sh_bytes_chunk1; sh_bytes_chunk2; sh_bytes_chunk3;
    sh_bytes_chunk4
  ]).

(* Total bytes = 4708 (from 1754 instructions); keys are byte
   addresses, so [sh_bytes !! addr] yields that byte. *)

Global Typeclasses Opaque sh_bytes.

(* KEY RANGE.  [sh_bytes_lo <= a < sh_bytes_hi] for every key [a]: the decidable
   [map_Forall] check, closed by one [vm_compute], so the proof term is
   [eq_refl] and no list ever enters it.  Bounds are LITERALS (this file
   is below iris/ and cannot name [ram_lo]/[text_end]/[img_end]); the
   consumer bridges them arithmetically. *)
Definition sh_bytes_lo : Z := 0x0%Z.
Definition sh_bytes_hi : Z := 0x1264%Z.

Lemma sh_bytes_range_bool :
  bool_decide (map_Forall (fun (a : Z) (_ : bv 8) =>
                 (sh_bytes_lo <= a < sh_bytes_hi)%Z) sh_bytes) = true.
Proof. vm_compute. reflexivity. Qed.

Lemma sh_bytes_range (a : Z) (b : bv 8) :
  sh_bytes !! a = Some b -> (sh_bytes_lo <= a < sh_bytes_hi)%Z.
Proof.
  pose proof sh_bytes_range_bool as H.
  apply bool_decide_eq_true_1 in H. exact (H a b).
Qed.

